#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_LEN 64

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);
    if (len1 > MAX_LEN || len2 > MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    static int dp[MAX_LEN + 1][MAX_LEN + 1];
    // initialize first row and column
    for (size_t i = 0; i <= len1; ++i) dp[i][0] = (int)i;
    for (size_t j = 0; j <= len2; ++j) dp[0][j] = (int)j;
    // fill DP table
    for (size_t i = 1; i <= len1; ++i) {
        for (size_t j = 1; j <= len2; ++j) {
            int cost = (s1[i-1] == s2[j-1]) ? 0 : 1;
            int del = dp[i-1][j] + 1;      // deletion
            int ins = dp[i][j-1] + 1;      // insertion
            int sub = dp[i-1][j-1] + cost; // substitution
            int min = del;
            if (ins < min) min = ins;
            if (sub < min) min = sub;
            dp[i][j] = min;
        }
    }
    printf("%d\n", dp[len1][len2]);
    return 0;
}
